import sys

MOD = 998244353


class ParityDSU:
    __slots__ = ("parent", "size", "xr", "components")

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.xr = [0] * n
        self.components = n

    def find(self, x):
        p = self.parent[x]
        if p == x:
            return x, 0
        r, d = self.find(p)
        self.xr[x] ^= d
        self.parent[x] = r
        return r, self.xr[x]

    def union(self, x, y, w):
        rx, dx = self.find(x)
        ry, dy = self.find(y)

        if rx == ry:
            return (dx ^ dy) == w

        if self.size[rx] > self.size[ry]:
            rx, ry = ry, rx
            dx, dy = dy, dx

        self.parent[rx] = ry
        self.xr[rx] = dx ^ dy ^ w
        self.size[ry] += self.size[rx]
        self.components -= 1
        return True


def solve_case(h, w, grid):
    # col_pref[j] stores XOR of A-types in rows 1..current_row-1.
    col_pref = [0] * w
    constraints = []

    for i, row in enumerate(grid):
        row_parity = 0
        horizontal_prefix = 0

        for j, ch in enumerate(row):
            is_a = 1 if ch == "A" else 0
            row_parity ^= is_a

            # Prefix of A-types in columns 1..j.
            if j > 0:
                horizontal_prefix ^= is_a

            if ch == "B":
                # h[i][j] = r_i XOR horizontal_prefix
                # v[i][j] = c_j XOR col_pref[j]
                # Type B requires h[i][j] XOR v[i][j] = 1.
                weight = 1 ^ horizontal_prefix ^ col_pref[j]
                constraints.append((i, h + j, weight))

        if row_parity:
            return 0

        # After processing row i, it contributes to vertical prefixes
        # only when i >= 1; row 0 is absorbed into the column closure test.
        if i >= 1:
            for j, ch in enumerate(row):
                if ch == "A":
                    col_pref[j] ^= 1

    # Column closure requires the XOR over all A-types in each column to be 0.
    first_row = grid[0]
    for j, ch in enumerate(first_row):
        if col_pref[j] ^ (1 if ch == "A" else 0):
            return 0

    dsu = ParityDSU(h + w)
    for x, y, parity in constraints:
        if not dsu.union(x, y, parity):
            return 0

    return pow(2, dsu.components, MOD)


def main():
    input = sys.stdin.buffer.readline
    t = int(input())
    answers = []

    for _ in range(t):
        h, w = map(int, input().split())
        grid = [input().strip().decode() for _ in range(h)]
        answers.append(str(solve_case(h, w, grid)))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    main()

import sys

MOD = 998244353
PRIMITIVE_ROOT = 3
NAIVE_LIMIT = 32


def ntt(a, invert):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(PRIMITIVE_ROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)

        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for i in range(start, start + half):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD

        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if not a or not b:
        return []

    need = len(a) + len(b) - 1

    if min(len(a), len(b)) <= NAIVE_LIMIT:
        result = [0] * need
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    result[i + j] = (result[i + j] + x * y) % MOD
        return result

    size = 1
    while size < need:
        size <<= 1

    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))

    ntt(fa, False)
    ntt(fb, False)

    for i in range(size):
        fa[i] = fa[i] * fb[i] % MOD

    ntt(fa, True)
    return fa[:need]


def solve():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (n + 1)
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # t[r] is the number of white vertices to the left of the
    # relevant cut for the bad event E_r.
    #
    # For r < n, use the cut immediately before the (r+1)-st black.
    # For r = n, use the cut immediately after the n-th black.
    t = [0] * (n + 1)
    black_count = 0
    white_count = 0

    for ch in s:
        if ch == "W":
            white_count += 1
        else:
            if black_count >= 1:
                t[black_count] = white_count
            black_count += 1
            if black_count == n:
                t[n] = white_count

    # dp[r] is the signed inclusion-exclusion contribution whose
    # last selected bad event is E_r. dp[0] represents no event.
    dp = [0] * (n + 1)
    dp[0] = 1

    def cdq(left, right):
        if right - left <= 1:
            return

        mid = (left + right) >> 1
        cdq(left, mid)

        max_t = -1
        for j in range(mid, right):
            if t[j] >= j and t[j] > max_t:
                max_t = t[j]

        if max_t >= mid:
            kernel = fact[:max_t - left + 1]
            product = convolution(dp[left:mid], kernel)

            for j in range(mid, right):
                if t[j] < j:
                    continue

                idx = t[j] - left
                contribution = product[idx] * invfact[t[j] - j] % MOD
                dp[j] = (dp[j] - contribution) % MOD

        cdq(mid, right)

    cdq(0, n + 1)

    answer = 0
    for r in range(n + 1):
        answer = (answer + dp[r] * fact[n - r]) % MOD

    print(answer)


if __name__ == "__main__":
    solve()

