from bisect import bisect_right
from math import isqrt


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    q = data[0]
    queries = data[1:1 + q]

    max_x = isqrt(max(queries))

    is_prime = bytearray(b"\x01") * (max_x + 1)
    if max_x >= 0:
        is_prime[0] = 0
    if max_x >= 1:
        is_prime[1] = 0

    for i in range(2, isqrt(max_x) + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start:max_x + 1:i] = b"\x00" * (((max_x - start) // i) + 1)

    distinct_count = bytearray(max_x + 1)
    for p in range(2, max_x + 1):
        if is_prime[p]:
            for multiple in range(p, max_x + 1, p):
                distinct_count[multiple] += 1

    candidates = [
        x * x
        for x in range(2, max_x + 1)
        if distinct_count[x] == 2
    ]
    candidates.sort()

    answers = [str(candidates[bisect_right(candidates, a) - 1]) for a in queries]
    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    main()

import sys

NEG = -(10**30)
INF = 10**30


def regular_sequence(vals, parity):
    n = len(vals)
    if parity > n:
        return None

    base = sum(vals[:parity])
    marginals = []
    for i in range(parity, n - 1, 2):
        marginals.append(vals[i] + vals[i + 1])

    return base, marginals, parity


def special_one_sequence(items, destination, parity):
    n = len(items)
    if n == 0:
        return None

    baseline = [item[0] for item in items]
    target = [item[destination + 1] for item in items]

    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + baseline[i]

    prefix_min_loss = [INF] * (n + 1)
    for i in range(n):
        loss = baseline[i] - target[i]
        prefix_min_loss[i + 1] = min(prefix_min_loss[i], loss)

    suffix_max_target = [NEG] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_max_target[i] = max(suffix_max_target[i + 1], target[i])

    best = [NEG] * (n + 1)
    for q in range(1, n + 1):
        value = prefix[q] - prefix_min_loss[q]

        if q < n:
            value = max(value, prefix[q - 1] + suffix_max_target[q])

        best[q] = value

    start = 1 if parity else 2
    if start > n or best[start] == NEG:
        return None

    marginals = []
    for q in range(start, n - 1, 2):
        marginals.append(best[q + 2] - best[q])

    return best[start], marginals, start


def special_two_sequence(items, destination_a, destination_b):
    n = len(items)
    if n < 2:
        return None

    baseline = [item[0] for item in items]
    gain_a = [
        item[destination_a + 1] - baseline[i]
        for i, item in enumerate(items)
    ]
    gain_b = [
        item[destination_b + 1] - baseline[i]
        for i, item in enumerate(items)
    ]

    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + baseline[i]

    suffix_a1 = [NEG] * (n + 1)
    suffix_a2 = [NEG] * (n + 1)
    suffix_ai = [-1] * (n + 1)

    suffix_b1 = [NEG] * (n + 1)
    suffix_b2 = [NEG] * (n + 1)
    suffix_bi = [-1] * (n + 1)

    for i in range(n - 1, -1, -1):
        candidates = [
            (gain_a[i], i),
            (suffix_a1[i + 1], suffix_ai[i + 1]),
            (suffix_a2[i + 1], -2),
        ]
        candidates.sort(reverse=True)

        chosen = []
        used = set()
        for value, index in candidates:
            if index >= 0 and index not in used:
                chosen.append((value, index))
                used.add(index)
        while len(chosen) < 2:
            chosen.append((NEG, -1))

        suffix_a1[i], suffix_ai[i] = chosen[0]
        suffix_a2[i] = chosen[1][0]

        candidates = [
            (gain_b[i], i),
            (suffix_b1[i + 1], suffix_bi[i + 1]),
            (suffix_b2[i + 1], -2),
        ]
        candidates.sort(reverse=True)

        chosen = []
        used = set()
        for value, index in candidates:
            if index >= 0 and index not in used:
                chosen.append((value, index))
                used.add(index)
        while len(chosen) < 2:
            chosen.append((NEG, -1))

        suffix_b1[i], suffix_bi[i] = chosen[0]
        suffix_b2[i] = chosen[1][0]

    best = [NEG] * (n + 1)
    best_a = (NEG, -1)
    best_b = (NEG, -1)
    best_pair = NEG

    for q in range(2, n + 1, 2):
        r = q - 2

        if r > 0:
            i = r - 1
            ga = gain_a[i]
            gb = gain_b[i]

            if best_b[1] != i:
                best_pair = max(best_pair, ga + best_b[0])
            if best_a[1] != i:
                best_pair = max(best_pair, gb + best_a[0])

            if ga > best_a[0]:
                best_a = (ga, i)
            if gb > best_b[0]:
                best_b = (gb, i)

        value = NEG

        if r >= 2:
            value = max(value, prefix[r] + best_pair)

        if r >= 1 and r < n:
            value = max(
                value,
                prefix[r] + best_a[0] + suffix_b1[r],
                prefix[r] + best_b[0] + suffix_a1[r],
            )

        if r < n:
            if suffix_ai[r] != suffix_bi[r]:
                outside = suffix_a1[r] + suffix_b1[r]
            else:
                outside = max(
                    suffix_a1[r] + suffix_b2[r],
                    suffix_b1[r] + suffix_a2[r],
                )
            value = max(value, prefix[r] + outside)

        best[q] = value

    if best[2] == NEG:
        return None

    marginals = []
    for q in range(2, n - 1, 2):
        marginals.append(best[q + 2] - best[q])

    return best[2], marginals, 2


def combine(sequences, total_count, incident):
    if any(sequence is None for sequence in sequences):
        return NEG

    for i, sequence in enumerate(sequences):
        if (sequence[2] + incident[i]) & 1:
            return NEG

    base = sum(sequence[0] for sequence in sequences)
    base_count = sum(sequence[2] for sequence in sequences)

    if total_count < base_count:
        return NEG
    if (total_count - base_count) & 1:
        return NEG

    need = (total_count - base_count) // 2
    marginals = []

    for sequence in sequences:
        marginals.extend(sequence[1])

    if need < 0 or need > len(marginals):
        return NEG

    marginals.sort(reverse=True)
    return base + sum(marginals[:need])


def solve_case(n, k, cakes):
    total = 2 * k
    groups = [[], [], []]

    for x, y, z in cakes:
        values = (x, y, z)
        owner = values.index(max(values))
        groups[owner].append((values[owner], x, y, z))

    for group in groups:
        group.sort(reverse=True)

    baseline_values = [
        [item[0] for item in group]
        for group in groups
    ]

    answer = combine(
        [regular_sequence(baseline_values[i], 0) for i in range(3)],
        total,
        (0, 0, 0),
    )

    for source in range(3):
        for destination in range(3):
            if source == destination:
                continue

            incident = [0, 0, 0]
            incident[source] = 1
            incident[destination] = 1

            sequences = []
            for i in range(3):
                if i == source:
                    sequences.append(
                        special_one_sequence(groups[source], destination, 1)
                    )
                elif i == destination:
                    sequences.append(regular_sequence(baseline_values[i], 1))
                else:
                    sequences.append(regular_sequence(baseline_values[i], 0))

            answer = max(answer, combine(sequences, total, tuple(incident)))

    for middle in range(3):
        first, second = [i for i in range(3) if i != middle]

        sequences = [None] * 3
        sequences[first] = special_one_sequence(groups[first], second, 1)
        sequences[middle] = special_one_sequence(groups[middle], second, 1)
        sequences[second] = regular_sequence(baseline_values[second], 0)
        answer = max(answer, combine(sequences, total, (1, 1, 2)))

        sequences = [None] * 3
        sequences[first] = regular_sequence(baseline_values[first], 1)
        sequences[middle] = regular_sequence(baseline_values[middle], 1)
        sequences[second] = special_two_sequence(
            groups[second], first, middle
        )
        answer = max(answer, combine(sequences, total, (1, 1, 2)))

        sequences = [None] * 3
        sequences[first] = special_one_sequence(groups[first], second, 1)
        sequences[middle] = regular_sequence(baseline_values[middle], 1)
        sequences[second] = special_one_sequence(groups[second], middle, 0)
        answer = max(answer, combine(sequences, total, (1, 0, 2)))

        sequences = [None] * 3
        sequences[first] = regular_sequence(baseline_values[first], 1)
        sequences[middle] = special_one_sequence(groups[middle], second, 1)
        sequences[second] = special_one_sequence(groups[second], first, 0)
        answer = max(answer, combine(sequences, total, (1, 0, 2)))

    return answer


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    t = next(it)
    answers = []

    for _ in range(t):
        n = next(it)
        k = next(it)

        cakes = [
            (next(it), next(it), next(it))
            for _ in range(n)
        ]

        answers.append(str(solve_case(n, k, cakes)))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    main()

import sys


def solve():
    input = sys.stdin.readline

    n = int(input())
    s = input().strip()
    t = input().strip()

    mapping = [-1] * 26

    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        if mapping[x] != -1 and mapping[x] != y:
            print(-1)
            return
        mapping[x] = y

    non_identity = sum(
        1 for x in range(26)
        if mapping[x] != -1 and mapping[x] != x
    )

    state = [0] * 26
    cycles = 0

    def dfs(v):
        nonlocal cycles
        state[v] = 1
        w = mapping[v]
        if w != -1 and w != v:
            if state[w] == 0:
                dfs(w)
            elif state[w] == 1:
                cycles += 1
        state[v] = 2

    for v in range(26):
        if mapping[v] != -1 and mapping[v] != v and state[v] == 0:
            dfs(v)

    if cycles > 0:
        used_in_target = [False] * 26
        for ch in t:
            used_in_target[ord(ch) - ord('a')] = True
        if all(used_in_target):
            print(-1)
            return

    print(non_identity + cycles)


if __name__ == "__main__":
    solve()

import sys

SHIFT = 500_000_000


def red_rectangle_cycle(n):
    if n == 2:
        return [(0, 0), (1, 0)]

    a = 1
    b = n // 2 - 1
    points = []
    x = y = 0

    for _ in range(a):
        points.append((x, y))
        x += 1
    for _ in range(b):
        points.append((x, y))
        y += 1
    for _ in range(a):
        points.append((x, y))
        x -= 1
    for _ in range(b):
        points.append((x, y))
        y -= 1

    return points


def blue_rectangle_cycle(n):
    return [(x + y, x - y) for x, y in red_rectangle_cycle(n)]


def mixed_cycle(red_count, blue_count):
    if blue_count & 1:
        k = (blue_count - 1) // 2

        grid_path = [(0, 0)]
        for j in range(1, k + 1):
            grid_path.append((0, -j))
        grid_path.append((1, -k))
        for y in range(-k + 1, 1):
            grid_path.append((1, y))

        start = (0, 0)
        finish = (1, 1)
    else:
        k = (blue_count - 2) // 2

        grid_path = [(0, 0)]
        for j in range(1, k + 1):
            grid_path.append((0, -j))
        grid_path.append((1, -k))
        for y in range(-k + 1, 2):
            grid_path.append((1, y))

        start = (0, 0)
        finish = (2, 0)

    blue_path = [(x + y, x - y) for x, y in grid_path]

    m = (red_count - 2) // 2
    red_path = [finish, (1, 0)]

    if m == 0:
        red_path.append(start)
    else:
        for j in range(1, m + 1):
            red_path.append((1, -j))
        red_path.append((0, -m))
        for j in range(m - 1, -1, -1):
            red_path.append((0, -j))

    result = []

    for r, c in red_path[:-1]:
        result.append(("R", r + SHIFT, c + SHIFT))

    for r, c in blue_path[:-1]:
        result.append(("B", r + SHIFT, c + SHIFT))

    return result


def solve_case(red_count, blue_count):
    if red_count & 1:
        return None

    if red_count == 0:
        if blue_count & 1:
            return None
        points = blue_rectangle_cycle(blue_count)
        return [("B", r + SHIFT, c + SHIFT) for r, c in points]

    if blue_count == 0:
        points = red_rectangle_cycle(red_count)
        return [("R", r + SHIFT, c + SHIFT) for r, c in points]

    return mixed_cycle(red_count, blue_count)


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    index = 1
    output = []

    for _ in range(t):
        red_count = data[index]
        blue_count = data[index + 1]
        index += 2

        answer = solve_case(red_count, blue_count)

        if answer is None:
            output.append("No")
        else:
            output.append("Yes")
            output.extend(
                f"{piece} {row} {col}"
                for piece, row, col in answer
            )

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    main()

import sys
from bisect import bisect_right

INF = 10**18


class SegmentTree:
    def __init__(self, n):
        size = 1
        while size < n:
            size <<= 1
        self.size = size
        self.data = [INF] * (2 * size)

    def set(self, index, value):
        p = index + self.size
        self.data[p] = value
        p >>= 1
        while p:
            self.data[p] = min(self.data[p << 1], self.data[p << 1 | 1])
            p >>= 1

    def minimum(self, left, right):
        if left >= right:
            return INF

        left += self.size
        right += self.size
        result = INF

        while left < right:
            if left & 1:
                result = min(result, self.data[left])
                left += 1
            if right & 1:
                right -= 1
                result = min(result, self.data[right])
            left >>= 1
            right >>= 1

        return result


def solve_case(a):
    n = len(a)

    positions = {}
    for i, value in enumerate(a):
        positions.setdefault(value, []).append(i)

    run_end = [n] * n
    for i in range(n - 2, -1, -1):
        if a[i] == a[i + 1]:
            run_end[i] = run_end[i + 1]
        else:
            run_end[i] = i + 1

    dp = [0] * (n + 1)
    seg = SegmentTree(n + 1)
    seg.set(n, 2 * n)

    for i in range(n - 1, -1, -1):
        best = 1 + dp[run_end[i]]

        if i + 1 < n and a[i] != a[i + 1]:
            same_positions = positions[a[i]]
            p = bisect_right(same_positions, i + 1)
            next_same = same_positions[p] if p < len(same_positions) else n

            middle_best = seg.minimum(i + 2, next_same)
            if middle_best < INF:
                best = min(best, 3 - 2 * (i + 2) + middle_best)

            if next_same < n:
                best = min(
                    best,
                    3 + 2 * (next_same - (i + 2))
                    + dp[run_end[next_same]],
                )
            else:
                best = min(best, 3 + 2 * (n - (i + 2)))

        dp[i] = best
        seg.set(i, dp[i] + 2 * i)

    return dp[0]


