    ndp = [0] * 16
    for state, ways in enumerate(dp):
        if ways:
            for nxt, multiplicity in tr[state]:
                ndp[nxt] += ways * multiplicity
    for i in range(16):
        ndp[i] %= MOD
    dp = ndp

# A cyclic orientation exists exactly when the resulting relation
# contains (0,0) or (1,1), i.e. one of the diagonal bits.
answer = 0
for state, ways in enumerate(dp):
    if state & 9:
        answer += ways

