        for v in g[u]:
            if parent[v] == u:
                best.append(down[v])
        if len(best) >= 3:
            best.sort(reverse=True)
            down[u] = 1 + best[0] + best[1] + best[2]

    # up[u] = message from parent[u] to u.
    up = [1] * n
    answer = -1

    for u in order:
        # Incoming arm values from all neighbors of u.
        top = []
        if parent[u] != n:
            top.append((up[u], parent[u]))
        for v in g[u]:
            if parent[v] == u:
                top.append((down[v], v))

        top.sort(reverse=True)
        if len(top) > 4:
            top = top[:4]

        # u can be the degree-4 center, choosing its best four arms.
        if len(g[u]) >= 4:
            answer = max(answer, 1 + sum(value for value, _ in top[:4]))

        # Compute messages from u to each child.
        for child in g[u]:
            if parent[child] != u:
                continue

            selected = []
            for value, neighbor in top:
                if neighbor != child:
                    selected.append(value)
                    if len(selected) == 3:
                        break

            if len(selected) == 3:
                up[child] = 1 + selected[0] + selected[1] + selected[2]
            else:
                up[child] = 1

    print(answer)


if __name__ == "__main__":
    solve()

import sys
import heapq

def solve():
    input = sys.stdin.readline
    n = int(input())
    graph = [input().strip() for _ in range(n)]

    incoming = [[set() for _ in range(26)] for _ in range(n)]
    outgoing = [[set() for _ in range(26)] for _ in range(n)]

    for u in range(n):
        row = graph[u]
        for v, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[u][c].add(v)
                incoming[v][c].add(u)

    total = n * n
    dist = [-1] * total
    unknown_rows = [set(range(n)) for _ in range(n)]
    heap = []

    for i in range(n):
        idx = i * n + i
        dist[idx] = 0
        unknown_rows[i].remove(i)
        heap.append((0, i, i))

    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch == '-':
                continue
            idx = u * n + v
            if dist[idx] == -1:
                dist[idx] = 1
                unknown_rows[u].remove(v)
                heap.append((1, u, v))

    heapq.heapify(heap)

    while heap:
        d, x, y = heapq.heappop(heap)
        if dist[x * n + y] != d:
            continue

        nd = d + 2
        for c in range(26):
            right = outgoing[y][c]
            if not right:
                continue

            for u in incoming[x][c]:
                row_unknown = unknown_rows[u]
                if not row_unknown:
                    continue

                candidates = row_unknown.intersection(right)
                if not candidates:
                    continue

                for v in candidates:
                    dist[u * n + v] = nd
                    heapq.heappush(heap, (nd, u, v))
                row_unknown.difference_update(candidates)

    out = []
    for i in range(n):
        out.append(" ".join(map(str, dist[i * n:(i + 1) * n])))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

from bisect import bisect_left


class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split("*")
        nonempty = [part for part in parts if part]

        if not nonempty:
            return 0

        def find_occurrences(pattern: str):
            m = len(pattern)
            lps = [0] * m

            j = 0
            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                lps[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = lps[j - 1]

            return result

        occurrences = [find_occurrences(part) for part in nonempty]

        if any(not positions for positions in occurrences):
            return -1

        if len(nonempty) == 1:
            return len(nonempty[0])

        answer = len(s) + 1
        first_length = len(nonempty[0])

        for first_start in occurrences[0]:
            previous_end = first_start + first_length
            last_end = None
            valid = True

            for index in range(1, len(nonempty)):
                positions = occurrences[index]
                next_index = bisect_left(positions, previous_end)

                if next_index == len(positions):
                    valid = False
                    break

                next_start = positions[next_index]
                previous_end = next_start + len(nonempty[index])
                last_end = previous_end

            if valid:
                answer = min(answer, last_end - first_start)

        return -1 if answer == len(s) + 1 else answer

