import sys

MOD = 998244353


def factorize(x):
    result = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            result.append((d, e))
        d += 1
    if x > 1:
        result.append((x, 1))
    return result


def prime_contribution(p, exponents, n):
    total_exp = sum(exponents)

    powers = [1] * (total_exp + 1)
    for i in range(1, total_exp + 1):
        powers[i] = powers[i - 1] * p % MOD

    # dp[y] is the total weight of normalized walks whose
    # current normalized height is y.
    dp = [0] * (total_exp + 1)
    dp[0] = 1
    current_max = 0

    for position, e in enumerate(exponents, start=1):
        nxt = [0] * (total_exp + 1)

        if e == 0:
            for y in range(current_max + 1):
                if dp[y]:
                    nxt[y] = dp[y] * powers[y] % MOD
            dp = nxt
            continue

        for y in range(current_max + 1):
            w = dp[y]
            if not w:
                continue

            # Positive signed difference: new height is y + e.
            z = y + e
            nxt[z] = (nxt[z] + w * powers[z]) % MOD

            # Negative signed difference: new raw height is y - e.
            if y >= e:
                z = y - e
                nxt[z] = (nxt[z] + w * powers[z]) % MOD
            else:
                # A new minimum is reached. The previous position
                # heights are all shifted upward by e - y.
                shift = e - y
                factor = pow(p, position * shift, MOD)
                nxt[0] = (nxt[0] + w * factor) % MOD

        dp = nxt
        current_max += e

    return sum(dp[:current_max + 1]) % MOD


def solve():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))

    prime_exponents = {}

    for i, value in enumerate(a):
        for p, e in factorize(value):
            if p not in prime_exponents:
                prime_exponents[p] = [0] * (n - 1)
            prime_exponents[p][i] = e

    answer = 1
    for p, exponents in prime_exponents.items():
        answer = answer * prime_contribution(p, exponents, n) % MOD

    print(answer)


if __name__ == "__main__":
    solve()

class Solution:
    def countSubstrings(self, s: str) -> int:
        # states[d][r] = number of substrings ending at the previous
        # position whose value is congruent to r modulo d.
        states = [None] + [[0] * d for d in range(1, 10)]
        answer = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for d in range(1, 10):
                old = states[d]
                updated = [0] * d

                for residue, count in enumerate(old):
                    updated[(residue * 10 + digit) % d] += count

                # The one-digit substring consisting of the current digit.
                updated[digit % d] += 1
                states[d] = updated

            if digit != 0:
                answer += states[digit][0]

        return answer

from typing import List


class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(target: int) -> bool:
            if target == 0:
                return True

            moves = 1
            visits = 1

            for i in range(n - 2):
                required = (target + points[i] - 1) // points[i]
                extra = max(0, required - visits)

                moves += 2 * extra + 1
                if moves > m:
                    return False

                visits = extra + 1

            required_second_last = (
                target + points[n - 2] - 1
            ) // points[n - 2]
            required_last = (
                target + points[n - 1] - 1
            ) // points[n - 1]

            round_trips = max(
                0,
                required_second_last - visits,
                required_last - 1,
            )
            moves += 2 * round_trips

            if round_trips < required_last:
                moves += 1

            return moves <= m

        low = 0
        high = max(points) * m + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

import sys


class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
        for i in range(1, n + 1):
            self.bit[i] = i & -i

    def kth(self, k):
        index = 0
        step = 1 << (self.n.bit_length() - 1)
        while step:
            nxt = index + step
            if nxt <= self.n and self.bit[nxt] < k:
                k -= self.bit[nxt]
                index = nxt
            step >>= 1
        return index + 1

    def add(self, index, value):
        while index <= self.n:
            self.bit[index] += value
            index += index & -index


def main():
