                    if p == source:
                        cur = 1
                    else:
                        cur = dp.get(p, 0)

                    if cur == 0:
                        continue

                    if i + 1 <= max_row:
                        q = p + W
                        if blocked[q]:
                            tid = index.get(q)
                            if tid is not None:
                                transition[sid][tid] += cur
                                if transition[sid][tid] >= MOD:
                                    transition[sid][tid] -= MOD
                        else:
                            dp[q] = (dp.get(q, 0) + cur * grid[q]) % MOD

                    if j + 1 <= max_col:
                        q = p + 1
                        if blocked[q]:
                            tid = index.get(q)
                            if tid is not None:
                                transition[sid][tid] += cur
                                if transition[sid][tid] >= MOD:
                                    transition[sid][tid] -= MOD
                        else:
                            dp[q] = (dp.get(q, 0) + cur * grid[q]) % MOD

        through = [0] * k

        for qi in range(left, right):
            d, value = queries[qi]

            if d == b"L":
                c -= 1
            elif d == b"R":
                c += 1
            elif d == b"U":
                r -= 1
            else:
                r += 1

            p = r * W + c
            grid[p] = value

            for v in range(k):
                total = entry[v]
                for u in range(k):
                    total += through[u] * transition[u][v]
                through[v] = grid[touched[v]] * (total % MOD) % MOD

            result = baseline
            for z in range(k):
                result += through[z] * exit_weight[z]

            answers.append(str(result % MOD))

        for p in touched:
            blocked[p] = 0

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    solve()

import sys


def matmul(a, b, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        ri = res[i]
        ai = a[i]
        for k, x in enumerate(ai):
            if x:
                bk = b[k]
                for j in range(n):
                    ri[j] += x * bk[j]
        for j in range(n):
            ri[j] %= mod
    return res


def matpow(a, e, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    base = a
    while e:
        if e & 1:
            res = matmul(res, base, mod)
        e >>= 1
        if e:
            base = matmul(base, base, mod)
    return res


def solve():
    input = sys.stdin.readline
    n, p = map(int, input().split())
    a = [list(map(int, input().split())) for _ in range(n)]

    if p == 2:
        b = [[1 if a[i][j] == 0 else a[i][j] for j in range(n)]
             for i in range(n)]
        ans = matmul(b, b, 2)
        print("\n".join(" ".join(map(str, row)) for row in ans))
        return

    k = sum(x == 0 for row in a for x in row)
    m = [row[:] for row in a]
    mp = matpow(m, p, p)

    c = [[0] * n for _ in range(n)]

    # Contribution DA + AD, where D marks zero diagonal entries.
    for u in range(n):
        if a[u][u] == 0:
            for v in range(n):
                c[u][v] += a[u][v]
                c[v][u] += a[v][u]

    # For p = 3, a non-loop zero edge can occur twice with its
    # nonzero reverse edge between the two occurrences.
    if p == 3:
        for u in range(n):
            for v in range(n):
                if u != v and a[u][v] == 0 and a[v][u] != 0:
                    c[u][v] += a[v][u]

    sign = 1 if k % 2 == 0 else p - 1
    ans = [[sign * (mp[i][j] + c[i][j]) % p for j in range(n)]
           for i in range(n)]

    print("\n".join(" ".join(map(str, row)) for row in ans))


if __name__ == "__main__":
    solve()

